function validate([flowers, people]) {
  if (!Array.isArray(flowers) || flowers.length < 1 || flowers.length > 50000) return 'flowers needs 1 to 50,000 pairs.';
  for (const flower of flowers) {
    if (!Array.isArray(flower) || flower.length !== 2 || !flower.every(Number.isInteger)) return 'Each flower is a pair [start, end] of integers.';
    if (flower[0] < 1 || flower[0] > flower[1] || flower[1] > 1e9) return 'Each flower needs 1 <= start <= end <= 10^9.';
  }
  if (!Array.isArray(people) || people.length < 1 || people.length > 50000) return 'people needs 1 to 50,000 times.';
  if (people.some(t => !Number.isInteger(t) || t < 1 || t > 1e9)) return 'Each arrival time is an integer from 1 to 10^9.';
  return null;
}

