function fullBloomFlowers(flowers, people) {
  const starts = flowers.map((flower) => flower[0]).sort((a, b) => a - b);
  const ends = flowers.map((flower) => flower[1]).sort((a, b) => a - b);

  const countBelow = (sorted, limit) => {
    let left = 0;
    let right = sorted.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (sorted[mid] < limit) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    return left;
  };

  const answer = [];
  for (const time of people) {
    const started = countBelow(starts, time + 1);
    const ended = countBelow(ends, time);
    answer.push(started - ended);
  }
  return answer;
}

