function fullBloomFlowers(flowers, people) {
  const result = [];
  for (let p = 0; p < people.length; p++) {
    let open = 0;
    for (const [s, e] of flowers) if (s <= people[p] && people[p] <= e) open++;
    result.push(open);
  }
  return result;
}

