function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const top = 1000000000;
    const flowers = Array.from({ length: 2000 }, () => {
      const start = int(1, top);
      const end = rand() < 0.5 ? Math.min(top, start + int(0, 50000000)) : int(start, top);
      return [start, end];
    });
    const people = Array.from({ length: 2000 }, () => rand() < 0.3 ? flowers[int(0, flowers.length - 1)][int(0, 1)] : int(1, top));
    return [flowers, people];
  }
  const span = int(3, 15);
  const flowers = Array.from({ length: int(1, 6) }, () => {
    const start = int(1, span);
    return [start, int(start, span)];
  });
  const people = Array.from({ length: int(1, 7) }, () => int(1, span + 1));
  return [flowers, people];
}
